                   RecipeIngredient(amount: "1", item: "yellow plantain, sliced in thick coins"),
                   RecipeIngredient(amount: "1/4 cup", item: "dried shrimp (or 1 tbsp shrimp paste)"),
                   RecipeIngredient(amount: "1/2 lb", item: "ground pork"),
                   RecipeIngredient(amount: "2", item: "onions, one sliced, one minced"),
                   RecipeIngredient(amount: "3", item: "garlic cloves, minced"),
                   RecipeIngredient(amount: "1 tsp", item: "cayenne pepper"),
                   RecipeIngredient(amount: "4 tbsp", item: "vegetable oil"),
                   RecipeIngredient(amount: "4", item: "banana leaves (frozen, from an Asian market; or parchment plus foil)"),
               ],
               steps: [
                   "Cook the rice in the stock with the cardamom and cloves until just short of done, about 15 minutes; it finishes inside the parcel.",
                   "Brown the chicken in a tablespoon of oil, add the sliced onion, half the garlic, and the dark-toasted curry powder, then simmer in the coconut milk until thick and clinging, about 25 minutes.",
                   "Fry the plantain coins in a little oil until deeply golden on both sides and set them aside on paper towels.",
                   "Grind or mince the dried shrimp, then fry it with the minced onion, remaining garlic, and cayenne until it darkens into a jammy, pungent blachan paste.",
                   "Season the ground pork with salt, roll it into eight small meatballs, and brown them in the same pan until cooked through.",
                   "Pass each banana leaf briefly over a flame or hot burner until it turns glossy and pliable; this is the moment the kitchen starts smelling right.",
                   "Center a mound of rice on each leaf, arrange chicken curry, two meatballs, plantain, and a spoon of blachan around it, and fold into a snug flat parcel, seam down.",
                   "Bake the parcels seam-down on a sheet pan at 350°F for 25 minutes and serve unopened, so each person gets the burst of leaf-scented steam.",
               ],
               note: "The bake inside the banana leaf is not packaging, it is the seasoning; a lamprais assembled and eaten unbaked is just rice with sides.",
               shortcut: "Skip the meatballs and double the chicken curry; the parcel loses one voice from the choir but still sings."),
        Recipe(dishID: "srilanka-ambulthiyal", serves: 4, prepMinutes: 15, cookMinutes: 45, difficulty: 2,
               ingredients: [
                   RecipeIngredient(amount: "1 1/2 lb", item: "fresh tuna steaks, cut in large 2-inch cubes"),
                   RecipeIngredient(amount: "6 pieces", item: "goraka (Sri Lankan grocer or online; or 3 tbsp tamarind paste)"),
                   RecipeIngredient(amount: "2 tsp", item: "coarsely ground black pepper"),
                   RecipeIngredient(amount: "4", item: "garlic cloves, crushed"),
                   RecipeIngredient(amount: "1 tsp", item: "grated fresh ginger"),
                   RecipeIngredient(amount: "10", item: "curry leaves (or leave them out)"),
                   RecipeIngredient(amount: "1/2 tsp", item: "cayenne pepper"),
                   RecipeIngredient(amount: "1 1/4 tsp", item: "salt"),
                   RecipeIngredient(amount: "1 tbsp", item: "coconut oil"),
                   RecipeIngredient(amount: "3/4 cup", item: "water"),
               ],
               steps: [
                   "Soak the goraka in half a cup of hot water for ten minutes until soft, then grind it into a dark paste with its liquid; tamarind paste just needs loosening with the water.",
                   "Work the sour paste with the black pepper, garlic, ginger, cayenne, and salt into a thick, almost black marinade.",
                   "Turn the tuna cubes gently in the marinade until every face is coated, and let them sit fifteen minutes while you find your widest shallow pan.",
                   "Arrange the fish in a single layer in the pan with the curry leaves and coconut oil, and pour the water carefully down the side, not over the fish.",
                   "Simmer uncovered on medium-low, turning each piece once with a spoon rather than stirring, until the liquid has nearly vanished, 25 to 30 minutes.",
                   "Keep cooking on the lowest heat until the pieces look dry, dark, and firm and the pan is barely slicked, about ten more minutes.",
                   "Rest at least half an hour before eating, or better, overnight at room temperature covered, as the fishing coast does; serve one or two pieces per person with rice.",
               ],
               note: "This is a dry dish on purpose; if there is sauce left, keep going. The sour and pepper should hit almost too hard next to plain rice.",
               shortcut: "Tamarind paste for goraka is the accepted substitute everywhere outside the island; the sourness is brighter and less resinous, and no one refuses the plate."),
        Recipe(dishID: "srilanka-stringhoppers", serves: 4, prepMinutes: 40, cookMinutes: 35, difficulty: 3,
               ingredients: [
                   RecipeIngredient(amount: "2 cups", item: "fine rice flour (red rice flour if you can find it)"),
                   RecipeIngredient(amount: "1 1/2 cups", item: "boiling water, more as needed"),
                   RecipeIngredient(amount: "1 1/4 tsp", item: "salt, divided"),
                   RecipeIngredient(amount: "1 cup", item: "red lentils"),
                   RecipeIngredient(amount: "1 can (13.5 oz)", item: "coconut milk, divided"),
                   RecipeIngredient(amount: "1/2 tsp", item: "ground turmeric"),
                   RecipeIngredient(amount: "10", item: "curry leaves (or leave them out)"),
                   RecipeIngredient(amount: "1 cup", item: "unsweetened shredded coconut"),
                   RecipeIngredient(amount: "1/2", item: "red onion, minced"),
                   RecipeIngredient(amount: "1 tsp", item: "crushed red pepper"),
                   RecipeIngredient(amount: "1", item: "lime"),
                   RecipeIngredient(amount: "1 tbsp", item: "vegetable oil"),
               ],
               steps: [
                   "Toast the rice flour in a dry pan two minutes without coloring it, then mix it with half the salt and pour in the boiling water in stages, stirring with a spoon.",
                   "Knead briefly once cool enough to touch; the dough should be smooth, hot, and soft enough to squeeze through a press without cracking.",
                   "Load a string hopper press, or a potato ricer fitted with its finest disc, and pipe small flat spirals of thread, about 4 inches across, onto lightly oiled steamer trays or plates.",
                   "Steam the nests over boiling water until they turn from chalky to translucent-white and spring back when pressed, 8 to 10 minutes.",
                   "Simmer the lentils with turmeric, curry leaves, and 2 cups water until collapsed, then stir in most of the coconut milk and the remaining salt for a loose, pourable dhal.",
                   "Moisten the shredded coconut with the last of the coconut milk and work in the onion, crushed pepper, lime juice, and a pinch of salt for a quick pol sambol.",
                   "Serve five or six nests per plate and let everyone break them up by hand, dousing with dhal and pinching sambol through the threads.",
               ],
               note: "Press the dough while it is still warm; cooled dough clogs the press and cracks. The nests should taste of almost nothing, and that is correct.",
               shortcut: "Thin rice vermicelli, briefly steamed and coiled into nests, gets you nine tenths of the way without buying a press."),
        Recipe(dishID: "srilanka-kiribath", serves: 6, prepMinutes: 5, cookMinutes: 40, difficulty: 1,
               ingredients: [
                   RecipeIngredient(amount: "2 cups", item: "short grain rice (sushi rice works)"),
                   RecipeIngredient(amount: "3 cups", item: "water"),
                   RecipeIngredient(amount: "1 can (13.5 oz)", item: "full-fat coconut milk"),
                   RecipeIngredient(amount: "1 1/4 tsp", item: "salt, divided"),
                   RecipeIngredient(amount: "1/2", item: "red onion, minced"),
                   RecipeIngredient(amount: "1 tbsp", item: "crushed red pepper"),
                   RecipeIngredient(amount: "1", item: "lime"),
                   RecipeIngredient(amount: "2 tbsp", item: "grated jaggery or brown sugar (optional, for the sweet camp)"),
               ],
               steps: [
                   "Rinse the rice once, then simmer it in the water, covered, until the water is absorbed and the grains are just tender, about 15 minutes.",
                   "Pour in the coconut milk and a teaspoon of salt and cook uncovered on low, stirring often, until it thickens to a stiff porridge that holds a spoon trail, 12 to 15 minutes.",
                   "Turn the hot rice onto a plate or into an 8-inch square pan and press it flat and even, about an inch thick, with the back of a wet spoon.",
                   "Rest it 15 to 20 minutes until set firm enough to slice, then cut it into diamonds with a wet knife.",
                   "Pound or grind the onion, crushed pepper, lime juice, and remaining salt into a coarse red lunu miris while the kiribath sets.",
                   "Serve the diamonds barely warm, with lunu miris for heat or a piece of jaggery for the sweet-toothed, and eat with your fingers as a proper new beginning demands.",
               ],
               note: "Cut only when fully set and keep the knife wet, or the diamonds crumble. The rice itself stays bland; the sambol is the flavor.",
               shortcut: "Leftover cooked rice reheated with coconut milk sets nearly as well, turning yesterday's rice pot into a festival breakfast in twenty minutes."),
        Recipe(dishID: "srilanka-watalappan", serves: 6, prepMinutes: 15, cookMinutes: 45, difficulty: 2,
               ingredients: [
                   RecipeIngredient(amount: "1 cup", item: "chopped kithul jaggery (or 1 cup dark brown sugar plus 1 tbsp molasses)"),
                   RecipeIngredient(amount: "3 tbsp", item: "water"),
                   RecipeIngredient(amount: "1 can (13.5 oz)", item: "full-fat coconut milk"),
                   RecipeIngredient(amount: "5", item: "large eggs"),
                   RecipeIngredient(amount: "1/2 tsp", item: "ground cardamom"),
                   RecipeIngredient(amount: "a pinch", item: "ground cloves"),
                   RecipeIngredient(amount: "a pinch", item: "grated nutmeg"),
                   RecipeIngredient(amount: "1/4 tsp", item: "salt"),
                   RecipeIngredient(amount: "1/3 cup", item: "roasted cashews, roughly chopped"),
               ],
               steps: [
                   "Melt the jaggery with the water over low heat, stirring until it dissolves into a dark syrup, then cool it until just warm to the touch.",
                   "Whisk the eggs gently in a large bowl, stirring rather than beating; froth now means bubbles baked into the custard later.",
                   "Stir in the coconut milk, warm syrup, cardamom, cloves, nutmeg, and salt, then strain the mixture through a sieve into a 1-quart baking dish or six ramekins.",
                   "Set the dish in a roasting pan, pour hot water halfway up its sides, and cover the pan loosely with foil.",
                   "Bake at 325°F until the custard is set at the edges with a slight wobble at the center, 35 to 45 minutes for a single dish, less for ramekins.",
                   "Cool to room temperature, then chill at least two hours; the texture tightens from soft-set to sliceable silk in the refrigerator.",
                   "Scatter the cashews over the top just before serving so they stay crisp against the smooth, dark custard.",
               ],
               note: "The wobble is the whole test: pull it while the center still shivers like set jelly. Overbaked watalappan weeps and turns grainy at the edges.",
               shortcut: "Steaming on the stovetop in a covered pot, 25 minutes over low heat, replaces the oven and water bath entirely."),
    ]

    private static let recipes_nepal: [Recipe] = [
        Recipe(dishID: "nepal-dalbhat", serves: 4, prepMinutes: 20, cookMinutes: 45, difficulty: 2,
               ingredients: [
