               shortcut: "All buckwheat flour, sold as farine de sarrasin in many supermarkets, works alone if millet flour proves hard to find."),
        Recipe(dishID: "nepal-jujudhau", serves: 6, prepMinutes: 15, cookMinutes: 45, difficulty: 2,
               ingredients: [
                   RecipeIngredient(amount: "1/2 gallon", item: "whole milk"),
                   RecipeIngredient(amount: "1 cup", item: "heavy cream (with the milk, the closest stand-in for buffalo milk)"),
                   RecipeIngredient(amount: "1/2 cup", item: "sugar"),
                   RecipeIngredient(amount: "5", item: "green cardamom pods, cracked"),
                   RecipeIngredient(amount: "2", item: "whole cloves"),
                   RecipeIngredient(amount: "3 tbsp", item: "plain yogurt with live active cultures"),
               ],
               steps: [
                   "Simmer the milk and cream with the cardamom and cloves in a wide, heavy pot, stirring often, until reduced by about a quarter, 30 to 40 minutes.",
                   "Stir in the sugar until dissolved, then pull out the whole spices and let the milk cool until a drop on your wrist feels warm but not hot, about 110°F.",
                   "Whisk the yogurt with a ladle of the warm milk until smooth, then stir it back into the pot gently and briefly.",
                   "Pour into an unglazed clay pot if you have one, which wicks out moisture overnight the Bhaktapur way, or a ceramic bowl if you do not.",
                   "Cover with a plate, wrap in a thick towel, and leave undisturbed in a turned-off oven with the light on for six to eight hours, until set.",
                   "Refrigerate at least four hours; the curd tightens into something thick enough to hold a spoon upright, and it is eaten straight from the pot it set in.",
               ],
               note: "Reduction is what separates this from ordinary yogurt: do not skip the simmer, and do not move the pot while it sets or it splits into curds and whey.",
               shortcut: "A new, well-scrubbed unglazed terracotta plant pot with no drainage hole does the clay pot's moisture-wicking work for a few dollars."),
    ]

    static let all: [Recipe] = recipes_india + recipes_srilanka + recipes_nepal
}
